package com.example.racquetcbr.service;
import com.example.racquetcbr.model.*; import org.springframework.stereotype.Service; import java.util.*;
@Service
public class RecommendationService {
 private final RacquetCsvRepository repo; private final JColibriSimilarityService sim;
 public RecommendationService(RacquetCsvRepository r,JColibriSimilarityService s){repo=r;sim=s;}
 public List<Recommendation> recommend(PlayerProfile q){ sim.createJColibriConfiguration(); return repo.findAll().stream().filter(c->eligible(q,c)).map(c->build(q,c)).sorted(Comparator.comparingDouble(Recommendation::score).reversed()).limit(q.getRecommendationCount()).toList(); }
 public List<Integer> availableYears(){return repo.findAll().stream().map(RacquetCase::getYear).filter(Objects::nonNull).distinct().sorted(Comparator.reverseOrder()).toList();}
 private boolean eligible(PlayerProfile q,RacquetCase c){ if("High".equalsIgnoreCase(q.getArmSensitivity())&&"High".equalsIgnoreCase(c.getArmRisk()))return false; boolean juniorQuery="Junior/Youth".equalsIgnoreCase(q.getAgeGroup()); boolean juniorCase="Junior/Youth".equalsIgnoreCase(c.getAgeGroup())||"Junior".equalsIgnoreCase(c.getPlayerLevel())||"Junior/Development".equalsIgnoreCase(c.getPrimaryStyle()); return juniorQuery==juniorCase; }
 private Recommendation build(PlayerProfile q,RacquetCase c){double score=sim.similarity(q,c); boolean brandSelected=q.getBrandPreference()!=null&&!q.getBrandPreference().isBlank(), yearSelected=q.getPreferredYear()!=null; if(brandSelected||yearSelected){score*=1-(brandSelected?0.15:0)-(yearSelected?0.15:0); if(brandSelected&&q.getBrandPreference().equalsIgnoreCase(c.getBrand()))score+=0.15; if(yearSelected&&q.getPreferredYear().equals(c.getYear()))score+=0.15;}
    List<String> reasons=new ArrayList<>(), cautions=new ArrayList<>(); if(eq(q.getPlayerLevel(),c.getPlayerLevel()))reasons.add("Exact player-level match"); if(eq(q.getPrimaryStyle(),c.getPrimaryStyle()))reasons.add("Matches your "+q.getPrimaryStyle().toLowerCase()+" playing style"); if(q.getPreferredYear()!=null&&q.getPreferredYear().equals(c.getYear()))reasons.add("Matches your selected year ("+c.getYear()+")"); if(q.getPreferredWeight()!=null&&c.getWeight()!=null)reasons.add(String.format("%.0f g frame is close to your preferred weight",c.getWeight())); if(q.getPreferredHeadSize()!=null&&c.getHeadSize()!=null)reasons.add(String.format("%.0f in² head size supports your selected profile",c.getHeadSize())); if("High".equalsIgnoreCase(c.getArmRisk()))cautions.add("High arm-risk classification; use a softer string setup and demo first"); if(c.getWeight()==null||c.getHeadSize()==null)cautions.add("Some specification fields are missing, reducing confidence"); String confidence=score>=.8?"High":score>=.65?"Medium":"Low"; return new Recommendation(c,Math.round(score*1000)/10.0,confidence,reasons,cautions); }
 private boolean eq(String a,String b){return a!=null&&b!=null&&a.equalsIgnoreCase(b);}
 public int caseCount(){return repo.size();}
}
